/// Pasteboard image reads for Ctrl+V (issue #276).
///
/// Platform glue only — the sniffing/capping rules live in `paste_image.dart`
/// (pure, which also owns the [PasteboardRead] result types). Every platform
/// path funnels through an injected [ProcessRunner] so tests script the
/// pasteboard instead of touching a real one.
///
/// - macOS: `osascript` writes `«class PNGf»` (fallback `«class JPEG»`) to a
///   temp file we then read. A TIFF-only pasteboard (Preview, most browsers)
///   holds neither (gh-1575): a third `«class TIFF»` probe lands the bytes in
///   a scratch file and `sips -s format png` converts them to PNG.
/// - Linux: `xclip -selection clipboard -t image/png -o`, falling back to
///   `wl-paste --type image/png` (Wayland).
/// - Windows: PowerShell `Get-Clipboard -Format Image` saved as PNG.
/// - `readPasteboardText` reads the clipboard's plain text the same way
///   (`pbpaste` / `xclip`+`wl-paste` / PowerShell `Get-Clipboard`) — the
///   Ctrl+V text fallback when the image probe misses (gh-1575).
/// - `FA_FAKE_PASTEBOARD=<path>` short-circuits the IMAGE read: that file
///   is returned as-is — the test seam for the PTY golden tests (and handy
///   for debugging on a headless box). The TEXT read has no fake seam —
///   it consults only the real platform pasteboard (script it with the
///   injected [ProcessRunner]).
library;

import 'dart:convert';
import 'dart:io';
import 'dart:typed_data' show BytesBuilder;

import 'paste_image.dart';
import 'pasteboard_platform.dart';

/// Runs a process to completion with stdout captured as RAW BYTES
/// (injectable `Process.run`). Binary mode is load-bearing: the default
/// text-mode decoding (UTF-8 on Linux) mangles pasteboard image bytes, so
/// the sniff downstream sees replacement chars instead of magic bytes.
typedef ProcessRunner =
    Future<ProcessResult> Function(String executable, List<String> args);

/// The default [ProcessRunner]: `Process.start` + an explicit stdout byte
/// fold — `Process.run` has no bytes mode, so the raw pipe is the only
/// lossless path. stderr is drained and discarded (exit codes carry
/// failures). The wait is bounded by [pasteboardProcessTimeout] (gh-1606
/// review): a wedged reader is killed and the wait surfaces as a
/// [TimeoutException] — the dispatchers map it into the named
/// unavailable result like any other read failure.
Future<ProcessResult> _runBinaryProcess(
  String executable,
  List<String> args,
) async {
  final process = await Process.start(executable, args);
  final wait = () async {
    final stdout = await process.stdout.fold(
      BytesBuilder(),
      (builder, chunk) => builder..add(chunk),
    );
    await process.stderr.drain<void>();
    final exitCode = await process.exitCode;
    return ProcessResult(process.pid, exitCode, stdout.toBytes(), null);
  }();
  return boundedPasteboardWait(wait, process);
}

/// The `FA_FAKE_PASTEBOARD` seam: reads the pinned file. `null` = no fake
/// configured (the caller falls through to the platform readers).
PasteboardRead? _readFakePasteboard(String? fake) {
  if (fake == null || fake.isEmpty) return null;
  try {
    return PasteboardImage(File(fake).readAsBytesSync());
  } on Object catch (error) {
    return PasteboardUnavailable('FA_FAKE_PASTEBOARD read failed: $error');
  }
}

/// Dispatches to the platform reader. Never throws (doc): a missing
/// xclip/osascript/powershell surfaces as a ProcessException here — turn
/// it into the named unavailable result the transcript prints as a clean
/// note (edge E1).
Future<PasteboardRead> _readPlatform(
  ProcessRunner run,
  Directory tmp,
  String? platform,
) async {
  try {
    switch (pasteboardPlatform(platform)) {
      case 'macos':
        return await _readMacos(run, tmp);
      case 'linux':
        return await _readLinux(run);
      case 'windows':
        return await _readWindows(run, tmp);
    }
  } on Object catch (error) {
    return PasteboardUnavailable('pasteboard read failed: $error');
  }
  return const PasteboardUnavailable('no pasteboard reader for this platform');
}

/// Reads the platform pasteboard's image content, trying each platform path
/// in order. Never throws — every failure becomes [PasteboardUnavailable].
Future<PasteboardRead> readPasteboardImage({
  ProcessRunner? runner,
  Directory? tempDir,
  Map<String, String> environment = const {},

  /// Pins the platform branch so unit tests can exercise every
  /// platform path (macOS/Windows readers are unreachable on a Linux
  /// CI runner, which would push their CRAP through the roof).
  String? platform,
}) async {
  final run = runner ?? _runBinaryProcess;
  // The explicit map wins (unit tests); the real process env is the seam
  // the PTY golden tests and headless debugging actually set.
  final fake = _readFakePasteboard(
    environment['FA_FAKE_PASTEBOARD'] ??
        Platform.environment['FA_FAKE_PASTEBOARD'],
  );
  if (fake != null) return fake;
  return _readPlatform(run, tempDir ?? Directory.systemTemp, platform);
}

Future<PasteboardRead> _readMacos(ProcessRunner runner, Directory tmp) async {
  for (final (appleClass, ext) in [
    ('«class PNGf»', 'png'),
    ('«class JPEG»', 'jpg'),
  ]) {
    final bytes = await _osascriptClipboardClassToFile(
      runner,
      tmp,
      appleClass,
      ext,
    );
    if (bytes != null) return PasteboardImage(bytes);
  }
  // gh-1575: TIFF-only pasteboards (an image copied from Preview or a
  // browser) hold neither PNGf nor JPEG — probe «class TIFF» and convert
  // to PNG with sips (ships with macOS). A failed conversion keeps the
  // unavailable fall-through: no silent garbage bytes ever become a chip.
  final tiff = await _osascriptClipboardClassToFile(
    runner,
    tmp,
    '«class TIFF»',
    'tiff',
  );
  if (tiff != null) {
    final png = await _convertTiffToPng(runner, tmp, tiff);
    if (png != null) return PasteboardImage(png);
  }
  return const PasteboardUnavailable('clipboard holds no image');
}

/// Asks osascript to write one clipboard flavor to a scratch file; the
/// bytes when the class was available and the file landed, else null. A
/// successful read drops the scratch file — a golden run pastes many
/// images and each would otherwise litter the temp dir.
Future<List<int>?> _osascriptClipboardClassToFile(
  ProcessRunner runner,
  Directory tmp,
  String appleClass,
  String ext,
) async {
  final target =
      '${tmp.path}/fa-clipboard-${DateTime.now().microsecondsSinceEpoch}'
      '.$ext';
  final script = [
    'set pngData to (the clipboard as $appleClass)',
    'set imgFile to (open for access POSIX file "$target" with write permission)',
    'try',
    'write pngData to imgFile',
    'close access imgFile',
    'on error errStr',
    'try',
    'close access imgFile',
    'end try',
    'error errStr',
    'end try',
  ];
  final result = await runner('osascript', [
    for (final line in script) ...['-e', line],
  ]);
  if (result.exitCode != 0) return null;
  try {
    final bytes = File(target).readAsBytesSync();
    File(target).deleteSync();
    return bytes;
  } on Object {
    return null;
  }
}

/// Converts TIFF [bytes] to PNG via `sips -s format png <in> --out <out>`;
/// the PNG bytes, or null when anything in the pipeline failed. Both
/// scratch files are cleaned up on every path.
Future<List<int>?> _convertTiffToPng(
  ProcessRunner runner,
  Directory tmp,
  List<int> bytes,
) async {
  final stamp = DateTime.now().microsecondsSinceEpoch;
  final tiffPath = '${tmp.path}/fa-clipboard-$stamp.tiff';
  final pngPath = '${tmp.path}/fa-clipboard-$stamp.png';
  try {
    File(tiffPath).writeAsBytesSync(bytes);
    final result = await runner('sips', [
      '-s',
      'format',
      'png',
      tiffPath,
      '--out',
      pngPath,
    ]);
    if (result.exitCode != 0) return null;
    return File(pngPath).readAsBytesSync();
  } on Object {
    return null;
  } finally {
    for (final path in [tiffPath, pngPath]) {
      try {
        final file = File(path);
        if (file.existsSync()) file.deleteSync();
      } on Object {
        // Best-effort cleanup — never mask the real outcome.
      }
    }
  }
}

/// Reads the platform pasteboard's TEXT content (gh-1575): `pbpaste`
/// (macOS), `xclip -selection clipboard -o` with a `wl-paste` fallback
/// (Linux), PowerShell `Get-Clipboard` (Windows). Never throws — every
/// failure becomes [PasteboardUnavailable]. Empty stdout counts as no
/// text: an empty paste must never reach the composer.
Future<PasteboardRead> readPasteboardText({
  ProcessRunner? runner,

  /// Pins the platform branch so unit tests can exercise every platform
  /// path (same seam as [readPasteboardImage]).
  String? platform,
}) async {
  final run = runner ?? _runBinaryProcess;
  try {
    switch (pasteboardPlatform(platform)) {
      case 'macos':
        return _textFromStdout(await run('pbpaste', const []));
      case 'linux':
        return await _readLinuxText(run);
      case 'windows':
        return await _readWindowsText(run);
    }
  } on Object catch (error) {
    return PasteboardUnavailable('pasteboard text read failed: $error');
  }
  return const PasteboardUnavailable('no pasteboard reader for this platform');
}

/// Decodes a text backend's stdout as UTF-8 (malformed bytes degrade to
/// replacement chars — never a throw); empty output = no text.
PasteboardRead _textFromStdout(ProcessResult result) {
  if (result.exitCode != 0) {
    return const PasteboardUnavailable('clipboard holds no text');
  }
  final stdout = result.stdout;
  final bytes = stdout is List<int> ? stdout : utf8.encode('$stdout');
  final text = utf8.decode(bytes, allowMalformed: true);
  if (text.isEmpty) {
    return const PasteboardUnavailable('clipboard holds no text');
  }
  return PasteboardText(text);
}

Future<PasteboardRead> _readLinuxText(ProcessRunner runner) async {
  // Type-pinned like the image path (gh-1575 review): unpinned wl-paste
  // pastes the FIRST MIME the source offers — for an image-only clipboard
  // the raw image bytes would reach the composer as "text". Pinned, both
  // backends fail cleanly and the named reason prints instead.
  for (final (executable, args) in [
    (
      'xclip',
      ['-selection', 'clipboard', '-t', 'text/plain;charset=utf-8', '-o'],
    ),
    ('wl-paste', ['--type', 'text/plain;charset=utf-8', '--no-newline']),
  ]) {
    final read = _textFromStdout(await runner(executable, args));
    if (read is PasteboardText) return read;
  }
  return const PasteboardUnavailable(
    'xclip/wl-paste unavailable or clipboard holds no text',
  );
}

Future<PasteboardRead> _readWindowsText(ProcessRunner runner) async {
  // Pin the console encoding (gh-1575 review): Windows PowerShell 5.1
  // writes redirected stdout in the OEM code page, so a UTF-8 decode of
  // an unpinned read mojibakes every non-ASCII character.
  final read = _textFromStdout(
    await runner('powershell', [
      '-NoProfile',
      '-Command',
      '[Console]::OutputEncoding=[System.Text.Encoding]::UTF8; Get-Clipboard',
    ]),
  );
  if (read is! PasteboardText) return read;
  // PowerShell's output formatter appends exactly one newline to the
  // captured stream — the clipboard text itself never carries it — and
  // formats every embedded line break as `\r\n`; normalize to `\n` (the
  // composer inserts verbatim, no `\r` normalization downstream).
  var text = read.text;
  if (text.endsWith('\r\n')) {
    text = text.substring(0, text.length - 2);
  } else if (text.endsWith('\n')) {
    text = text.substring(0, text.length - 1);
  }
  text = text.replaceAll('\r\n', '\n');
  if (text.isEmpty) {
    return const PasteboardUnavailable('clipboard holds no text');
  }
  return PasteboardText(text);
}

/// Linux: `xclip -selection clipboard -t image/png -o`, falling back to
/// `wl-paste --type image/png` (Wayland). The runner hands stdout back as
/// raw bytes — image payloads are binary, and text-mode decoding would
/// mangle the magic bytes the sniff depends on (review major 2).
Future<PasteboardRead> _readLinux(ProcessRunner runner) async {
  for (final (executable, args) in [
    ('xclip', ['-selection', 'clipboard', '-t', 'image/png', '-o']),
    ('wl-paste', ['--type', 'image/png', '--no-newline']),
  ]) {
    final result = await runner(executable, args);
    final stdout = result.stdout;
    if (result.exitCode == 0 && stdout is List<int> && stdout.isNotEmpty) {
      return PasteboardImage(stdout);
    }
  }
  return const PasteboardUnavailable(
    'xclip/wl-paste unavailable or clipboard holds no image',
  );
}

Future<PasteboardRead> _readWindows(ProcessRunner runner, Directory tmp) async {
  final target =
      '${tmp.path}\\fa-clipboard-${DateTime.now().microsecondsSinceEpoch}'
      '.png';
  final script =
      'Add-Type -AssemblyName System.Windows.Forms;'
      'Add-Type -AssemblyName System.Drawing;'
      r'$img = [System.Windows.Forms.Clipboard]::GetImage();'
      'if (\$img -eq \$null) { exit 2 }'
      '\$img.Save("$target", [System.Drawing.Imaging.ImageFormat]::Png)';
  final result = await runner('powershell', ['-NoProfile', '-Command', script]);
  final image = result.exitCode == 0 ? _readSavedPng(target) : null;
  return image ?? const PasteboardUnavailable('clipboard holds no image');
}

/// Reads and deletes the PowerShell-saved PNG; null when missing or broken
/// (the caller reports plain unavailability either way).
PasteboardRead? _readSavedPng(String target) {
  try {
    final bytes = File(target).readAsBytesSync();
    File(target).deleteSync();
    return PasteboardImage(bytes);
  } on Object {
    // Fall through.
    return null;
  }
}

/// Shared pasteboard platform glue (gh-1606 review): the effective-platform
/// resolution and the bounded-subprocess wait used by BOTH pasteboard sides
/// — `clipboard_reader.dart` (Ctrl+V image/text reads, gh-1575) and
/// `clipboard_writer.dart` (`/provider export` text writes, gh-1606).
///
/// One copy, not two: the platform resolution was a byte-identical
/// duplicate in the reader and the writer and would drift (e.g. a new
/// platform arm added to one side only). dart:io — both importers are
/// IO-only libraries behind the web-safe conditional-import pattern (web
/// builds get the `*_stub.dart` variants and never see this file).
library;

import 'dart:async';
import 'dart:io';

/// The hard wall-clock bound for one pasteboard subprocess (read or
/// write): a wedged binary (a shadowed `pbcopy` script, `xclip` blocking
/// on a dead `$DISPLAY`) must not hold the caller forever — the
/// `/provider export` flow gate stays shut while its write runs, so an
/// unbounded writer would no-op every later `/provider …` flow until the
/// process restarts (gh-1606 review).
const pasteboardProcessTimeout = Duration(seconds: 5);

/// The effective platform id (`macos`/`linux`/`windows`): the explicit
/// [platform] pin wins (unit tests — the macOS/Windows paths are
/// unreachable on a Linux CI runner, which would push their CRAP through
/// the roof), else the host [Platform]. `null` = no pasteboard glue for
/// this platform.
String? pasteboardPlatform(String? platform) {
  if (platform != null) return platform;
  if (Platform.isMacOS) return 'macos';
  if (Platform.isLinux) return 'linux';
  if (Platform.isWindows) return 'windows';
  return null;
}

/// Awaits [wait] bounded by [timeout]; on expiry [process] is killed (a
/// wedged pasteboard binary must not leak one process per call either)
/// and the wait surfaces as a [TimeoutException] the caller maps to its
/// named unavailable result.
Future<T> boundedPasteboardWait<T>(
  Future<T> wait,
  Process process, {
  Duration timeout = pasteboardProcessTimeout,
}) async {
  try {
    return await wait.timeout(timeout);
  } on TimeoutException {
    process.kill();
    rethrow;
  }
}

/// Clipboard image paste (issue #276): pure sniffing / capping / naming.
///
/// The dart_tui REPL binds Ctrl+V to a pasteboard read (platform glue in
/// `clipboard_reader.dart`). The bytes land here: magic-byte sniffing decides
/// image vs not, the size cap turns an oversized clipboard into a NAMED error
/// (never a silent truncation), and the attachment carries the chip label the
/// composer renders. Pure Dart — no `dart:io` — so the web stub and the tests
/// share the exact rules the real reader enforces.
library;

/// The byte cap for a pasted image (10 MiB). A bigger clipboard is rejected
/// with the size IN the error plus a downscale suggestion — edge case E4.
const maxPasteImageBytes = 10 * 1024 * 1024;

/// Magic-byte signatures, checked in order (same set the `inspect_image`
/// tool sniffs).
const _imageMagicSignatures = [
  ('image/png', <int>[0x89, 0x50]),
  ('image/jpeg', <int>[0xFF, 0xD8]),
  ('image/gif', <int>[0x47, 0x49, 0x46]),
  ('image/webp', <int>[0x52, 0x49]), // RIFF
];

/// Sniffs the image MIME type from magic bytes; `null` when [bytes] do not
/// start with a known image signature (a text clipboard, a PDF, …).
String? sniffImageMime(List<int> bytes) {
  if (bytes.length < 8) return null;
  for (final (mimeType, magic) in _imageMagicSignatures) {
    var matches = true;
    for (var i = 0; i < magic.length; i++) {
      if (bytes[i] != magic[i]) {
        matches = false;
        break;
      }
    }
    if (matches) return mimeType;
  }
  return null;
}

/// The canonical file extension for a sniffed image MIME type.
String imageMimeExtension(String mimeType) => switch (mimeType) {
  'image/jpeg' => 'jpg',
  'image/png' => 'png',
  'image/gif' => 'gif',
  'image/webp' => 'webp',
  _ => 'bin',
};

/// Human-readable byte size for chips and errors: raw B under 1 KiB, KiB
/// under 1 MiB, MiB above (one decimal).
String formatPasteBytes(int bytes) {
  if (bytes < 1024) return '${bytes}B';
  if (bytes < 1024 * 1024) {
    final kib = bytes / 1024;
    return kib == kib.roundToDouble()
        ? '${kib.toStringAsFixed(0)}KB'
        : '${kib.toStringAsFixed(1)}KB';
  }
  final mib = bytes / (1024 * 1024);
  return '${mib.toStringAsFixed(1)}MB';
}

/// An image pasted from the clipboard, waiting in the composer as a chip.
final class TuiImageAttachment {
  const TuiImageAttachment({
    required this.name,
    required this.mimeType,
    required this.bytes,
  });

  /// File name in the session images store (`clipboard-3.png`).
  final String name;

  /// Sniffed MIME type (`image/png`).
  final String mimeType;

  /// Raw image bytes (base64-encoded only at send time).
  final List<int> bytes;

  /// The composer chip label: `[image: clipboard-3.png 248KB]`.
  String get chip => '[image: $name ${formatPasteBytes(bytes.length)}]';
}

/// Validates clipboard [bytes] as a paster-able image.
///
/// Returns the error text when the paste must be rejected (oversized or not
/// an image — both NAMED), `null` when the bytes are good.
String? pasteImageError(List<int> bytes) {
  if (bytes.length > maxPasteImageBytes) {
    return 'clipboard image too large: ${formatPasteBytes(bytes.length)} '
        '(cap ${formatPasteBytes(maxPasteImageBytes)}) — downscale the image '
        'and paste again';
  }
  if (sniffImageMime(bytes) == null) {
    return 'clipboard does not hold a recognized image '
        '(png/jpeg/gif/webp magic bytes expected)';
  }
  return null;
}

/// The outcome of a pasteboard read: image bytes, or a named failure
/// reason. Pure data — the IO glue in `clipboard_reader.dart` produces it,
/// the REPL consumes it (both behind the same web-safe import).
sealed class PasteboardRead {
  const PasteboardRead();
}

final class PasteboardImage extends PasteboardRead {
  const PasteboardImage(this.bytes);

  /// Raw image bytes (sniffed/capped downstream).
  final List<int> bytes;
}

/// No image reachable — carries the failure reason for the transcript.
final class PasteboardUnavailable extends PasteboardRead {
  const PasteboardUnavailable(this.reason);
  final String reason;
}

/// The outcome of a pasteboard WRITE (`/provider export`, gh-1606): the
/// text landed, or a named failure reason. Pure data — the IO glue in
/// `clipboard_writer.dart` produces it, the REPL consumes it (both behind
/// the same web-safe import).
sealed class PasteboardWriteResult {
  const PasteboardWriteResult();
}

/// The text is on the clipboard.
final class PasteboardWriteOk extends PasteboardWriteResult {
  const PasteboardWriteOk();
}

/// The clipboard refused or no writer exists — carries the failure reason
/// for the transcript (the copied text itself never surfaces).
final class PasteboardWriteUnavailable extends PasteboardWriteResult {
  const PasteboardWriteUnavailable(this.reason);
  final String reason;
}

/// TEXT clipboard content (gh-1575): the Ctrl+V image probe falls back to
/// the platform text reader (`pbpaste` / xclip / Get-Clipboard) when the
/// pasteboard holds no image — the composer inserts [text] instead of
/// printing the image probe's dead-end reason. Produced only by the IO
/// glue in `clipboard_reader.dart`; a text result never carries image
/// bytes, so it can never become a chip.
final class PasteboardText extends PasteboardRead {
  const PasteboardText(this.text);

  /// The clipboard's plain text (UTF-8 decoded, untrimmed).
  final String text;
}

/// The clean note for a terminal with no reachable pasteboard (edge E1):
/// names what happened and the file-path fallback.
const clipboardUnavailableHint =
    'clipboard has no image (terminal or pasteboard unavailable) — '
    'save the screenshot to a file and paste its path instead';

/// Pasteboard reader tests (issue #276, review major 2): the Linux paste
/// path must treat stdout as RAW BYTES. `Process.run`'s default text-mode
/// decoding (UTF-8) mangles image payloads — replacement chars where the
/// magic bytes should be — so the reader runs its processes through a
/// binary pipe and the glue must not re-decode.
library;

import 'dart:convert';
import 'dart:io';

import 'package:flutter_agent_harness/src/cli/clipboard_reader.dart';
import 'package:flutter_agent_harness/src/cli/paste_image.dart';
import 'package:test/test.dart';

/// A PNG signature followed by NON-UTF8 bytes (0xFF 0xFE): any text-mode
/// decode round-trip replaces them and the equality below fails.
final _pngish = <int>[
  0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A, //
  0x00, 0xFF, 0xFE, 0x42,
];

ProcessResult _ok(List<int> stdout) => ProcessResult(1, 0, stdout, null);

void main() {
  test('the Linux path hands the raw bytes through untouched', () async {
    Future<ProcessResult> runner(String executable, List<String> args) async =>
        _ok(_pngish);
    final read = await readPasteboardImage(runner: runner, platform: 'linux');
    expect(read, isA<PasteboardImage>());
    expect((read as PasteboardImage).bytes, _pngish);
  });

  test('a failing first backend falls through to the next one', () async {
    var calls = 0;
    Future<ProcessResult> runner(String executable, List<String> args) async {
      calls++;
      return calls == 1 ? ProcessResult(1, 1, '', 'nope') : _ok(_pngish);
    }

    final read = await readPasteboardImage(runner: runner, platform: 'linux');
    expect(calls, 2, reason: 'xclip failed → wl-paste tried');
    expect((read as PasteboardImage).bytes, _pngish);
  });

  test('no backend reachable names the failure (edge E1 shape)', () async {
    Future<ProcessResult> runner(String executable, List<String> args) async =>
        ProcessResult(1, 1, '', 'not found');
    final read = await readPasteboardImage(runner: runner, platform: 'linux');
    expect(read, isA<PasteboardUnavailable>());
    expect((read as PasteboardUnavailable).reason, contains('xclip'));
  });

  test('the real binary pipe neither throws nor mangles', () async {
    // Without xclip/wl-paste installed this lands on the unavailable
    // path — the assertion is that the default binary runner completes
    // cleanly and returns bytes (or the named unavailable), never a
    // decoded String.
    final read = await readPasteboardImage(environment: const {});
    expect(read, anyOf(isA<PasteboardUnavailable>(), isA<PasteboardImage>()));
  }, skip: !Platform.isLinux);

  test('FA_FAKE_PASTEBOARD short-circuits to a file read', () async {
    final dir = await Directory.systemTemp.createTemp('fa_pasteboard');
    addTearDown(() => dir.deleteSync(recursive: true));
    final file = File('${dir.path}/fake.png')..writeAsBytesSync(_pngish);
    final read = await readPasteboardImage(
      environment: {'FA_FAKE_PASTEBOARD': file.path},
    );
    expect((read as PasteboardImage).bytes, _pngish);
  });

  test('the macOS path reads the scratch file the script wrote', () async {
    Future<ProcessResult> runner(String exe, List<String> args) async {
      expect(exe, 'osascript');
      // The script embeds the target path: the fake osascript honors it
      // exactly like the real one — write the image, exit 0.
      final script = args.join(' ');
      final match = RegExp(r'POSIX file "([^"]+)"').firstMatch(script)!;
      File(match.group(1)!).writeAsBytesSync(_pngish);
      return _ok(const []);
    }

    final read = await readPasteboardImage(runner: runner, platform: 'macos');
    expect(read, isA<PasteboardImage>());
    expect((read as PasteboardImage).bytes, _pngish);
  });

  test(
    'the macOS path falls through PNG to JPEG to TIFF, then gives up',
    () async {
      var calls = 0;
      Future<ProcessResult> runner(String exe, List<String> args) async {
        calls++;
        return ProcessResult(1, 1, '', 'clipboard holds no image');
      }

      final read = await readPasteboardImage(runner: runner, platform: 'macos');
      expect(calls, 3, reason: 'PNGf tried, then JPEG, then the TIFF fallback');
      expect(read, isA<PasteboardUnavailable>());
    },
  );

  // --- gh-1575: a TIFF-only pasteboard (Preview, browsers) must paste ---

  test('a TIFF-only macOS pasteboard converts to PNG via sips', () async {
    const tiff = <int>[0x4D, 0x4D, 0x00, 0x2A, 0xDE, 0xAD];
    final png = _pngish;
    Future<ProcessResult> runner(String exe, List<String> args) async {
      final script = args.join(' ');
      if (exe == 'osascript') {
        if (!script.contains('«class TIFF»')) {
          return ProcessResult(1, 1, '', 'no image of this class');
        }
        final match = RegExp(r'POSIX file "([^"]+)"').firstMatch(script)!;
        File(match.group(1)!).writeAsBytesSync(tiff);
        return _ok(const []);
      }
      expect(exe, 'sips');
      expect(args.take(3), ['-s', 'format', 'png']);
      final out = args[args.indexOf('--out') + 1];
      File(out).writeAsBytesSync(png);
      return _ok(const []);
    }

    final read = await readPasteboardImage(runner: runner, platform: 'macos');
    expect(read, isA<PasteboardImage>());
    expect((read as PasteboardImage).bytes, png);
  });

  test('a failing TIFF→PNG conversion falls through to unavailable', () async {
    Future<ProcessResult> runner(String exe, List<String> args) async {
      final script = args.join(' ');
      if (exe == 'osascript') {
        if (!script.contains('«class TIFF»')) {
          return ProcessResult(1, 1, '', 'no image of this class');
        }
        final match = RegExp(r'POSIX file "([^"]+)"').firstMatch(script)!;
        File(match.group(1)!).writeAsBytesSync(const [1, 2, 3, 4]);
        return _ok(const []);
      }
      return ProcessResult(1, 1, '', 'sips failed'); // conversion breaks
    }

    final read = await readPasteboardImage(runner: runner, platform: 'macos');
    expect(read, isA<PasteboardUnavailable>());
    expect((read as PasteboardUnavailable).reason, contains('no image'));
  });

  // --- gh-1575: readPasteboardText — the Ctrl+V text fallback ---

  test('the macOS text path reads pbpaste', () async {
    Future<ProcessResult> runner(String exe, List<String> args) async {
      expect(exe, 'pbpaste');
      return _ok(utf8.encode('hello clipboard'));
    }

    final read = await readPasteboardText(runner: runner, platform: 'macos');
    expect(read, isA<PasteboardText>());
    expect((read as PasteboardText).text, 'hello clipboard');
  });

  test('an empty pbpaste result is a named unavailable', () async {
    Future<ProcessResult> runner(String exe, List<String> args) async =>
        _ok(const []);
    final read = await readPasteboardText(runner: runner, platform: 'macos');
    expect(read, isA<PasteboardUnavailable>());
  });

  test('the Linux text path falls back from xclip to wl-paste', () async {
    var calls = 0;
    Future<ProcessResult> runner(String exe, List<String> args) async {
      calls++;
      return calls == 1
          ? ProcessResult(1, 1, '', 'nope')
          : _ok(utf8.encode('wayland text'));
    }

    final read = await readPasteboardText(runner: runner, platform: 'linux');
    expect(calls, 2, reason: 'xclip failed → wl-paste tried');
    expect((read as PasteboardText).text, 'wayland text');
  });

  test('the Windows text path strips the one PowerShell newline', () async {
    Future<ProcessResult> runner(String exe, List<String> args) async {
      expect(exe, 'powershell');
      return _ok(utf8.encode('windows text\r\n'));
    }

    final read = await readPasteboardText(runner: runner, platform: 'windows');
    expect((read as PasteboardText).text, 'windows text');
  });

  test('no text backend reachable names the failure', () async {
    Future<ProcessResult> runner(String exe, List<String> args) async =>
        ProcessResult(1, 1, '', 'not found');
    final read = await readPasteboardText(runner: runner, platform: 'linux');
    expect(read, isA<PasteboardUnavailable>());
    expect((read as PasteboardUnavailable).reason, contains('xclip'));
  });

  // --- gh-1575 review: the text backends must be encoding- and type-pinned ---

  test('the Windows text command pins UTF-8 on the console encoding', () async {
    String? command;
    Future<ProcessResult> runner(String exe, List<String> args) async {
      expect(exe, 'powershell');
      command = args.last;
      return _ok(utf8.encode('windows text\r\n'));
    }

    await readPasteboardText(runner: runner, platform: 'windows');
    // Windows PowerShell 5.1 writes redirected stdout in the OEM code
    // page; without this pin every non-ASCII clipboard character lands
    // in the composer as U+FFFD (review important 2).
    expect(
      command,
      contains('[Console]::OutputEncoding=[System.Text.Encoding]::UTF8'),
    );
