// fa-clip — native NSPasteboard image read for the Fa CLI (gh-2040).
//
// gh-2040: the CLI's macOS paste-image probe used to ride osascript
// (`the clipboard as «class PNGf»`) — an Apple Events delivery gated by
// TCC kTCCServiceSystemPolicyAppData on macOS 15+, which surfaced the
// recurring «"fa" would like to access data from other apps» dialog.
// Reading NSPasteboard directly sends no Apple Events, so that consent
// class never fires: no entitlements, no Automation entry, no prompt —
// on any macOS version, signed or not.
//
// Usage: fa-clip <png|jpeg|tiff>
//  exit 0  — the flavor's bytes on stdout
//  exit 2  — the pasteboard holds no data of the requested flavor
//  exit 1  — the pasteboard could not be read (message on stderr)
//  exit 64 — usage error (message on stderr)
//
// The Dart side (lib/src/cli/clipboard_reader.dart) keeps the flavor
// ladder PNG → JPEG → TIFF (+ sips PNG conversion): this helper answers
// ONE flavor per invocation and exits 2 when that flavor is absent.

import AppKit

let flavorArgs: [String: NSPasteboard.PasteboardType] = [
   "png": NSPasteboard.PasteboardType("public.png"),
   "jpeg": NSPasteboard.PasteboardType("public.jpeg"),
   "tiff": NSPasteboard.PasteboardType("public.tiff"),
]

guard CommandLine.arguments.count == 2,
     let flavor = flavorArgs[CommandLine.arguments[1].lowercased()] else {
   FileHandle.standardError.write(Data("usage: fa-clip <png|jpeg|tiff>\n".utf8))
   exit(64)
}

guard let data = NSPasteboard.general.data(forType: flavor) else {
   exit(2) // flavor absent — the caller's ladder falls through
}
FileHandle.standardOutput.write(data)
exit(0)
``

